/**
 * Supabase Edge Function: send-sms
 *
 * Custom SMS hook for Supabase Auth phone OTP.
 * GoTrue calls this hook with { phone, otp } when a user requests phone auth.
 * We use the Twilio REST API to send the SMS.
 */
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

interface SmsHookPayload {
  phone: string;
  otp: string;
  type?: string;
  user?: { id: string; phone: string };
  factor_id?: string;
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const payload: SmsHookPayload = await req.json();
    const { phone, otp } = payload;

    if (!phone || !otp) {
      return new Response(
        JSON.stringify({ error: "Missing phone or otp" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Get Twilio credentials from Supabase Vault / environment
    const accountSid = Deno.env.get("TWILIO_ACCOUNT_SID");
    const authToken = Deno.env.get("TWILIO_AUTH_TOKEN");
    const messagingServiceSid = Deno.env.get("TWILIO_MESSAGING_SERVICE_SID");
    const fromNumber = Deno.env.get("TWILIO_FROM_NUMBER");

    if (!accountSid || !authToken) {
      console.error("Twilio credentials not configured in Supabase Edge Function secrets.");
      return new Response(
        JSON.stringify({ error: "SMS provider not configured" }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Call Twilio REST API to send SMS
    const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
    const encodedAuth = btoa(`${accountSid}:${authToken}`);

    const formBody = new URLSearchParams();
    formBody.append("To", phone);
    formBody.append("Body", `Your VitaHero verification code is: ${otp}`);

    if (messagingServiceSid) {
      formBody.append("MessagingServiceSid", messagingServiceSid);
    } else if (fromNumber) {
      formBody.append("From", fromNumber);
    }

    const twilioResp = await fetch(twilioUrl, {
      method: "POST",
      headers: {
        "Authorization": `Basic ${encodedAuth}`,
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: formBody.toString(),
    });

    const twilioData = await twilioResp.json();

    if (!twilioResp.ok) {
      console.error("Twilio error:", twilioData);
      return new Response(
        JSON.stringify({ error: "SMS send failed", detail: twilioData }),
        { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    console.log(`SMS sent to ${phone}: ${twilioData.sid}`);
    return new Response(
      JSON.stringify({ success: true, sid: twilioData.sid }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (err) {
    console.error("send-sms error:", err);
    return new Response(
      JSON.stringify({ error: "Internal server error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

