/**
 * Supabase Edge Function: send-sms
 *
 * Dual-mode SMS sender for VitaHero phone OTP.
 *
 * Mode 1 — Supabase Auth Hook (GoTrue calls us automatically):
 *   POST { phone, otp }  → sends SMS via Twilio.
 *   Credentials from Supabase Edge Function secrets (TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN)
 *   or from the x-twilio-account-sid / x-twilio-auth-token headers.
 *
 * Mode 2 — Direct API call (app calls us directly):
 *   POST { phone, otp, app: true }
 *   Same as Mode 1 but returns the OTP confirmation.
 */

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-twilio-account-sid, x-twilio-auth-token",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

interface SmsPayload {
  phone: string;
  otp: string;
  app?: boolean;
}

async function sendTwilioSms(
  phone: string,
  body: string,
  accountSid: string,
  authToken: string,
): Promise<{ ok: boolean; sid?: string; error?: string }> {
  const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
  const encodedAuth = btoa(`${accountSid}:${authToken}`);

  const formBody = new URLSearchParams();
  formBody.append("To", phone);
  formBody.append("Body", body);
  // Use a Twilio phone number or messaging service — configure in secrets
  const fromNumber = Deno.env.get("TWILIO_FROM_NUMBER");
  const messagingServiceSid = Deno.env.get("TWILIO_MESSAGING_SERVICE_SID");
  if (messagingServiceSid) {
    formBody.append("MessagingServiceSid", messagingServiceSid);
  } else if (fromNumber) {
    formBody.append("From", fromNumber);
  }

  const resp = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Basic ${encodedAuth}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: formBody.toString(),
  });

  const data = await resp.json();
  if (!resp.ok) {
    console.error("Twilio error:", data);
    return { ok: false, error: data.message || "SMS send failed" };
  }
  console.log(`SMS sent to ${phone}: ${data.sid}`);
  return { ok: true, sid: data.sid };
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const payload: SmsPayload = await req.json();
    const { phone, otp } = payload;

    if (!phone || !otp) {
      return new Response(
        JSON.stringify({ error: "Missing phone or otp" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // Resolve Twilio credentials: prefer secrets, fall back to request headers
    let accountSid = Deno.env.get("TWILIO_ACCOUNT_SID");
    let authToken = Deno.env.get("TWILIO_AUTH_TOKEN");

    if (!accountSid) {
      accountSid = req.headers.get("x-twilio-account-sid") ?? "";
    }
    if (!authToken) {
      authToken = req.headers.get("x-twilio-auth-token") ?? "";
    }

    if (!accountSid || !authToken) {
      console.error("Twilio credentials missing — set TWILIO_ACCOUNT_SID / TWILIO_AUTH_TOKEN secrets or pass via headers.");
      return new Response(
        JSON.stringify({ error: "SMS provider not configured. Set Twilio secrets in Supabase Dashboard." }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const smsBody = `Your VitaHero verification code is: ${otp}`;
    const result = await sendTwilioSms(phone, smsBody, accountSid, authToken);

    if (!result.ok) {
      return new Response(
        JSON.stringify({ error: result.error }),
        { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    return new Response(
      JSON.stringify({ success: true, sid: result.sid }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (err) {
    console.error("send-sms error:", err);
    return new Response(
      JSON.stringify({ error: "Internal server error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }
});

