-- When GoTrue generates a phone OTP, it will POST { phone, otp } to this URL.

-- Set the SMS hook URL in auth configuration
DO $$
BEGIN
  -- Try setting via auth.config if available (Supabase-specific)
  BEGIN
    UPDATE auth.config
    SET value = '"https://klmgvvsikkhzgfxfujua.supabase.co/functions/v1/send-sms"'
    WHERE parameter = 'hook.send_sms_uri';

    IF NOT FOUND THEN
      INSERT INTO auth.config (parameter, value)
      VALUES ('hook.send_sms_uri', '"https://klmgvvsikkhzgfxfujua.supabase.co/functions/v1/send-sms"');
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- auth.config table might not exist or be accessible
    RAISE NOTICE 'Could not set SMS hook via auth.config: %', SQLERRM;
  END;
END $$;

-- Also try the vault approach for storing hook URL
DO $$
BEGIN
  BEGIN
    PERFORM vault.create_secret(
      'AUTH_HOOK_SEND_SMS_URI',
