/** Send OTP to phone number (format: +919876543210).
 *  Primary path: GoTrue /auth/v1/otp (requires Twilio configured in Supabase Auth).
 *  Falls back to direct Edge Function call with Twilio credential headers. */
suspend fun sendPhoneOtp(phone: String, twilioSid: String = "", twilioToken: String = ""): Result<Unit> = onIo {
    try {
        // First try GoTrue's built-in OTP endpoint
        val body = buildJsonObject {
            put("phone", phone)
        }
        val goTrueResp = http.post("$baseUrl/auth/v1/otp") {
            authHeaders().forEach { (k, v) -> header(k, v) }
            contentType(ContentType.Application.Json)
            setBody(body.toString())
        }
        // GoTrue returns 200 even if SMS provider isn't configured —
        // the OTP is generated but SMS may not be sent.
        // If we have Twilio credentials, also send via our Edge Function.
        if (twilioSid.isNotBlank() && twilioToken.isNotBlank()) {
            sendViaEdgeFunction(phone, twilioSid, twilioToken)
        }
        Result.success(Unit)
    } catch (e: Exception) {
        // GoTrue failed entirely — try Edge Function as fallback
        if (twilioSid.isNotBlank() && twilioToken.isNotBlank()) {
            try {
                sendViaEdgeFunction(phone, twilioSid, twilioToken)
                Result.success(Unit)
            } catch (e2: Exception) {
                Result.failure(e2)
            }
        } else {
            Result.failure(e)
        }
    }
}

/** Call our Edge Function to send SMS via Twilio directly.
 *  The Edge Function URL is configured in Config.kt / BuildConfig. */
private suspend fun sendViaEdgeFunction(phone: String, twilioSid: String, twilioToken: String) {
    val edgeFnUrl = buildString {
        append(Config.allValues["SUPABASE_SEND_SMS_URL"]
            ?: "https://klmgvvsikkhzgfxfujua.supabase.co/functions/v1/send-sms")
    }
    // Generate a 6-digit OTP locally and send it via the edge function.
    // Note: This OTP is sent via SMS but Supabase GoTrue's /auth/v1/verify
    // expects the OTP that GoTrue generated. For production, configure
    // Twilio in Supabase Auth dashboard or set the SMS hook URL there.
    val localOtp = (100000..999999).random().toString()
    val smsBody = buildJsonObject {
        put("phone", phone)
        put("otp", localOtp)
        put("app", true)
    }
    http.post(edgeFnUrl) {
        header("Content-Type", "application/json")
        header("x-twilio-account-sid", twilioSid)
        header("x-twilio-auth-token", twilioToken)
        contentType(ContentType.Application.Json)
        setBody(smsBody.toString())
    }
    // Store the locally-generated OTP for verification
    _pendingLocalOtp = localOtp
    _pendingLocalPhone = phone
}

