/**
 * Supabase Edge Function: send-sms
 *
 * Complete phone-auth OTP flow for VitaHero.
 *
 * Endpoints:
 *   POST { action: "send_otp", phone: "+919876543210" }
 *     → Generates 6-digit OTP, stores salted SHA-256 hash in phone_otps table,
 *       sends SMS via Twilio. Returns { success, expiresIn: 300 }.
 *
 *   POST { action: "verify_otp", phone: "+919876543210", otp: "123456" }
 *     → Verifies OTP hash. On success, creates/finds the Supabase Auth user
 *       (phone identity), returns { success, user_id, phone }.
 *       The Android app then calls Supabase GoTrue's standard token endpoint
 *       to finalize the session.
 *
 * Twilio credentials: passed via request headers (x-twilio-account-sid,
 * x-twilio-auth-token) from the Android app, which gets them from Rork's
 * private environment variables at build time.
 */

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-twilio-account-sid, x-twilio-auth-token",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

// ── Crypto helpers ──────────────────────────────────────────

async function sha256(text: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(text);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
}

function generateOtp(): string {
  const digits = new Uint8Array(6);
  crypto.getRandomValues(digits);
  return Array.from(digits, (d) => (d % 10).toString()).join("");
}

// ── Twilio SMS ──────────────────────────────────────────────

async function sendTwilioSms(
  phone: string,
  body: string,
  accountSid: string,
  authToken: string,
): Promise<{ ok: boolean; sid?: string; error?: string }> {
  const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
  const encodedAuth = btoa(`${accountSid}:${authToken}`);

  const formBody = new URLSearchParams();
  formBody.append("To", phone);
  formBody.append("Body", body);

  const fromNumber = Deno.env.get("TWILIO_FROM_NUMBER");
  const messagingServiceSid = Deno.env.get("TWILIO_MESSAGING_SERVICE_SID");
  if (messagingServiceSid) {
    formBody.append("MessagingServiceSid", messagingServiceSid);
  } else if (fromNumber) {
    formBody.append("From", fromNumber);
  }

  const resp = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Basic ${encodedAuth}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: formBody.toString(),
  });

  const data = await resp.json();
  if (!resp.ok) {
    console.error("Twilio error:", data);
    return { ok: false, error: data.message || "SMS send failed" };
  }
  console.log(`SMS sent to ${phone}: ${data.sid}`);
  return { ok: true, sid: data.sid };
}

// ── Supabase admin client ───────────────────────────────────

function getAdminClient() {
  return createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
  );
}

// ── Phone normalization ─────────────────────────────────────

function normalizePhone(phone: string): string {
  let normalized = phone.replace(/\s+/g, "").trim();
  if (!normalized.startsWith("+")) {
    normalized = "+" + normalized;
  }
  return normalized;
}

// ── Main handler ────────────────────────────────────────────

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const payload = await req.json();
    const action = payload.action as string;

    if (action === "send_otp") {
      return await handleSendOtp(req, payload);
    } else if (action === "verify_otp") {
      return await handleVerifyOtp(req, payload);
    } else if (payload.phone && payload.otp) {
      // Legacy hook mode: GoTrue calls us with { phone, otp }
      return await handleSendOtp(req, { ...payload, action: "send_otp" });
    } else {
      return new Response(
        JSON.stringify({ error: "Missing action. Use { action: 'send_otp' | 'verify_otp' }" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }
  } catch (err) {
    console.error("send-sms error:", err);
    return new Response(
      JSON.stringify({ error: "Internal server error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }
});

// ── Action: send_otp ────────────────────────────────────────

async function handleSendOtp(req: Request, payload: Record<string, unknown>) {
  const phone = normalizePhone((payload.phone as string) || "");

  if (!phone || phone.length < 10) {
    return new Response(
      JSON.stringify({ error: "Valid phone number required" }),
      { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  // Resolve Twilio credentials
  let accountSid = Deno.env.get("TWILIO_ACCOUNT_SID");
  let authToken = Deno.env.get("TWILIO_AUTH_TOKEN");
  if (!accountSid) accountSid = req.headers.get("x-twilio-account-sid") ?? "";
  if (!authToken) authToken = req.headers.get("x-twilio-auth-token") ?? "";

  if (!accountSid || !authToken) {
    return new Response(
      JSON.stringify({ error: "SMS provider not configured. Set Twilio secrets in the Supabase Dashboard or pass credentials via headers." }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  // Generate OTP
  const otp = payload.otp as string || generateOtp();
  const salt = crypto.randomUUID();
  const otpHash = await sha256(`${phone}:${otp}:${salt}`);

  // Store OTP hash in database
  const supabase = getAdminClient();
  const { error: dbError } = await supabase
    .from("phone_otps")
    .insert({
      phone,
      otp_hash: otpHash,
      salt,
      expires_at: new Date(Date.now() + 5 * 60 * 1000).toISOString(),
    });

  if (dbError) {
    console.error("Failed to store OTP:", dbError);
    return new Response(
      JSON.stringify({ error: "Failed to generate OTP" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  // Send SMS via Twilio
  const smsBody = `Your VitaHero verification code is: ${otp}`;
  const result = await sendTwilioSms(phone, smsBody, accountSid, authToken);

  if (!result.ok) {
    return new Response(
      JSON.stringify({ error: result.error }),
      { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  return new Response(
    JSON.stringify({ success: true, expiresIn: 300 }),
    { headers: { ...corsHeaders, "Content-Type": "application/json" } },
  );
}

// ── Action: verify_otp ──────────────────────────────────────

async function handleVerifyOtp(req: Request, payload: Record<string, unknown>) {
  const phone = normalizePhone((payload.phone as string) || "");
  const otp = (payload.otp as string) || "";

  if (!phone || otp.length !== 6) {
    return new Response(
      JSON.stringify({ error: "Phone and 6-digit OTP required" }),
      { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  const supabase = getAdminClient();

  // Find all unverified, non-expired OTPs for this phone
  const { data: otpRecords, error: lookupError } = await supabase
    .from("phone_otps")
    .select("*")
    .eq("phone", phone)
    .eq("verified", false)
    .gt("expires_at", new Date().toISOString())
    .order("created_at", { ascending: false })
    .limit(5);

  if (lookupError || !otpRecords || otpRecords.length === 0) {
    return new Response(
      JSON.stringify({ error: "No active OTP found. Request a new code." }),
      { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  // Try to match the OTP against stored salted hashes
  let matchedRecord: (typeof otpRecords)[0] | null = null;

  for (const record of otpRecords) {
    const testHash = await sha256(`${phone}:${otp}:${record.salt || ""}`);
    if (testHash === record.otp_hash) {
      matchedRecord = record;
      break;
    }
  }

  if (!matchedRecord) {
    return new Response(
      JSON.stringify({ error: "Invalid OTP. Please try again." }),
      { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  // Mark OTP as verified
  await supabase
    .from("phone_otps")
    .update({ verified: true })
    .eq("id", matchedRecord.id);

  // Create or find the Supabase Auth user for this phone
  const { data: existingUsers } = await supabase.auth.admin.listUsers();

  let userId: string | null = null;

  if (existingUsers?.users) {
    const existing = existingUsers.users.find(
      (u) => u.phone === phone,
    );
    if (existing) {
      userId = existing.id;
    }
  }

  if (!userId) {
    // Create a new user with phone identity
    const { data: newUser, error: createError } = await supabase.auth.admin.createUser({
      phone,
      phone_confirm: true,
      user_metadata: { name: "Parent", signup_method: "phone" },
    });

    if (createError || !newUser?.user) {
      console.error("Failed to create user:", createError);
      return new Response(
        JSON.stringify({ error: "Failed to create account" }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }
    userId = newUser.user.id;
  }

  return new Response(
    JSON.stringify({
      success: true,
      user_id: userId,
      phone,
      message: "OTP verified. User authenticated.",
    }),
    { headers: { ...corsHeaders, "Content-Type": "application/json" } },
  );
}

