/**
 * Verify phone OTP via the Edge Function + GoTrue session.
 * @param phone phone number WITH country code (e.g. "+919876543210")
 */
suspend fun verifyPhoneOtp(phone: String, token: String): Result<AuthResponse> = onIo {
    try {
        // Step 1: Verify OTP via Edge Function
        val verifyBody = buildJsonObject {
            put("action", "verify_otp")
            put("phone", phone)
            put("otp", token)
        }
        val verifyResp = http.post(edgeFnUrl) {
            header("Content-Type", "application/json")
            contentType(ContentType.Application.Json)
            setBody(verifyBody.toString())
        }
        val verifyResult = verifyResp.body<EdgeFnOtpResponse>()

        if (!verifyResult.success) {
            return@onIo Result.failure(Exception(verifyResult.error ?: "Invalid OTP"))
        }

        val userId = verifyResult.user_id ?: ""
        if (userId.isBlank()) {
            return@onIo Result.failure(Exception("User creation failed"))
        }

        // Step 2: Get session tokens from GoTrue
        // Since the user was created by admin API, we sign them in via phone
        val sessionBody = buildJsonObject {
            put("phone", phone)
            put("token", token)
            put("type", "sms")
        }
        val sessionResp = http.post("$baseUrl/auth/v1/verify") {
            authHeaders().forEach { (k, v) -> header(k, v) }
            contentType(ContentType.Application.Json)
            setBody(sessionBody.toString())
        }
        Result.success(sessionResp.body<AuthResponse>())
    } catch (e: Exception) {
        Result.failure(e)
    }
}

